-- Migration and release history vs. schema evidence (READ-ONLY).
-- Target: First Zagotowki, ssheqxdgsmndiutthxvd (also runs unchanged on UAT).
-- Run the WHOLE file: the visible result is H4 (one row per repository migration / Storage policy file).
-- H1-H3 can be run on their own with "Run selected". Nothing is written.
--
-- Production has no Supabase CLI history (supabase_migrations.schema_migrations does not exist there): changes were
-- applied through supabase/upgrades/production/*.sql and recorded in the private journal
-- app_private.production_module_releases. Absence of a history entry therefore proves nothing; H4 decides from the
-- schema itself: every table, column, constraint, index, trigger, policy, bucket the migration introduces, and every
-- function body it defines (md5 of the source, matched against all repository versions of that function).
--   CONFIRMED APPLIED      all evidence present (function bodies at this version or a later one)
--   CONFIRMED NOT APPLIED  none of its objects present and every function body older than this migration
--   PARTIALLY APPLIED      some evidence present, some absent
--   APPLIED, BODIES DIFFER objects present but some function bodies match no repository version (PROD-specific patch?)
--   UNKNOWN                the migration introduces nothing that can be observed (data-only / no-op)
--   HISTORY MISMATCH       a history or journal entry contradicts the schema evidence

-- H1. Production release journal (empty result when the journal does not exist, e.g. on UAT).
SELECT (xpath('/row/release/text()', r))[1]::text AS release,
       (xpath('/row/applied_at/text()', r))[1]::text AS applied_at,
       replace(replace(replace((xpath('/row/manifest/text()', r))[1]::text, '&lt;', '<'), '&gt;', '>'), '&amp;', '&') AS manifest
FROM unnest(xpath('/table/row', query_to_xml(CASE WHEN to_regclass('app_private.production_module_releases') IS NULL
       THEN 'SELECT NULL::text AS release, NULL::text AS applied_at, NULL::text AS manifest WHERE false'
       ELSE 'SELECT release, applied_at::text AS applied_at, manifest::text AS manifest FROM app_private.production_module_releases ORDER BY applied_at, release' END,
       false, false, ''))) AS r;

-- H2. Legacy Production upgrade state (production_upgrade; empty when absent).
SELECT (xpath('/row/state/text()', r))[1]::text AS production_upgrade_row
FROM unnest(xpath('/table/row', query_to_xml(CASE WHEN to_regclass('app_private.production_upgrade') IS NULL
       THEN 'SELECT NULL::text AS state WHERE false'
       ELSE 'SELECT to_jsonb(u)::text AS state FROM app_private.production_upgrade u' END, false, false, ''))) AS r;

-- H3. Supabase CLI history (empty when the table does not exist, as on Production).
SELECT (xpath('/row/version/text()', r))[1]::text AS version, (xpath('/row/name/text()', r))[1]::text AS name
FROM unnest(xpath('/table/row', query_to_xml(CASE
       WHEN to_regclass('supabase_migrations.schema_migrations') IS NULL THEN 'SELECT NULL::text AS version, NULL::text AS name WHERE false'
       WHEN EXISTS (SELECT FROM pg_attribute WHERE attrelid = to_regclass('supabase_migrations.schema_migrations') AND attname = 'name' AND NOT attisdropped)
         THEN 'SELECT version::text AS version, name::text AS name FROM supabase_migrations.schema_migrations ORDER BY version'
       ELSE 'SELECT version::text AS version, NULL::text AS name FROM supabase_migrations.schema_migrations ORDER BY version' END,
       false, false, ''))) AS r;

