),
act_objects AS (
  SELECT 'table' AS kind, n.nspname || '.' || c.relname AS object, '' AS def FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname IN ('public', 'app_private') AND c.relkind IN ('r', 'p', 'v', 'm')
  UNION ALL SELECT 'column', n.nspname || '.' || c.relname || '.' || a.attname,
   format_type(a.atttypid, a.atttypmod) || '|' || a.attnotnull::text || '|' ||
   coalesce(CASE WHEN a.attidentity <> '' THEN 'identity ' || CASE a.attidentity WHEN 'a' THEN 'always' ELSE 'by default' END ELSE pg_get_expr(d.adbin, d.adrelid) END, '')
   FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace
   LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
   WHERE n.nspname IN ('public', 'app_private') AND c.relkind IN ('r', 'p', 'v', 'm') AND a.attnum > 0 AND NOT a.attisdropped
  UNION ALL SELECT 'constraint', n.nspname || '.' || c.relname || '.' || k.conname, k.contype::text || ' ' || pg_get_constraintdef(k.oid)
   FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('public', 'app_private')
  UNION ALL SELECT 'index', schemaname || '.' || indexname, indexdef FROM pg_indexes WHERE schemaname IN ('public', 'app_private')
  UNION ALL SELECT 'trigger', n.nspname || '.' || c.relname || '.' || g.tgname, pg_get_triggerdef(g.oid) || ' ' || g.tgenabled::text
   FROM pg_trigger g JOIN pg_class c ON c.oid = g.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname IN ('public', 'app_private') AND NOT g.tgisinternal
  UNION ALL SELECT 'policy', schemaname || '.' || tablename || '.' || policyname,
   cmd || '|' || array_to_string(roles, ',') || '|' || coalesce(qual, '') || '|' || coalesce(with_check, '')
   FROM pg_policies WHERE schemaname IN ('public', 'app_private', 'storage')
  UNION ALL SELECT 'bucket', id, public::text || '|' || coalesce(file_size_limit::text, '') || '|' || array_to_string(ARRAY(SELECT unnest(allowed_mime_types) ORDER BY 1), ',') FROM storage.buckets
), act_functions AS (
  SELECT n.nspname || '.' || p.proname || '(' || oidvectortypes(p.proargtypes) || ')' AS object, md5(p.prosrc) AS md5
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname IN ('public', 'app_private')
), exp_objects AS (
  SELECT 'table' AS kind, object, '' AS def, introduced_by, changed_by FROM exp_tables
  UNION ALL SELECT 'column', object, data_type || '|' || not_null::text || '|' || coalesce(default_expr, ''), introduced_by, changed_by FROM exp_columns
  UNION ALL SELECT 'constraint', object, contype || ' ' || definition, introduced_by, changed_by FROM exp_constraints
  UNION ALL SELECT 'index', object, definition, introduced_by, changed_by FROM exp_indexes
  UNION ALL SELECT 'trigger', object, definition || ' ' || enabled, introduced_by, changed_by FROM exp_triggers
  UNION ALL SELECT 'policy', object, cmd || '|' || roles || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), introduced_by, changed_by FROM exp_policies
  UNION ALL SELECT 'bucket', object, public::text || '|' || file_size_limit || '|' || mime_types, introduced_by, changed_by FROM exp_buckets
), evidence AS (
  -- the migration that introduces an object: the object exists (a policy must also carry its expected rule)
  SELECT x.introduced_by AS migration,
         (a.object IS NOT NULL AND (x.kind <> 'policy' OR btrim(regexp_replace(x.def, '\s+', ' ', 'g')) = btrim(regexp_replace(a.def, '\s+', ' ', 'g')))) AS present,
         false AS unknown_body
  FROM exp_objects x LEFT JOIN act_objects a ON a.kind = x.kind AND a.object = x.object
  UNION ALL
  -- a later migration that redefines an existing object: the current definition must match
  SELECT x.changed_by, a.object IS NOT NULL AND btrim(regexp_replace(x.def, '\s+', ' ', 'g')) = btrim(regexp_replace(a.def, '\s+', ' ', 'g')), false
  FROM exp_objects x LEFT JOIN act_objects a ON a.kind = x.kind AND a.object = x.object
  WHERE x.changed_by <> x.introduced_by
  UNION ALL
  -- each function version this migration defines: deployed body at this version or later = evidence present
  SELECT v.migration, dv.version_no::int >= v.version_no::int, (f.object IS NOT NULL AND dv.version_no IS NULL)
  FROM exp_function_versions v
  LEFT JOIN act_functions f ON f.object = v.object
  LEFT JOIN exp_function_versions dv ON dv.object = v.object AND dv.md5 = f.md5
), per_migration AS (
  SELECT migration, count(*) AS objects_expected,
         count(*) FILTER (WHERE present) AS present,
         count(*) FILTER (WHERE NOT coalesce(present, false) AND NOT unknown_body) AS absent,
         count(*) FILTER (WHERE unknown_body) AS unknown_bodies
  FROM evidence GROUP BY migration
), journal AS (
  SELECT (xpath('/row/release/text()', r))[1]::text AS release, (xpath('/row/manifest/text()', r))[1]::text AS manifest
  FROM unnest(xpath('/table/row', query_to_xml(CASE WHEN to_regclass('app_private.production_module_releases') IS NULL
         THEN 'SELECT NULL::text AS release, NULL::text AS manifest WHERE false'
         ELSE 'SELECT release, manifest::text AS manifest FROM app_private.production_module_releases' END, false, false, ''))) AS r
), cli AS (
  SELECT (xpath('/row/version/text()', r))[1]::text AS version
  FROM unnest(xpath('/table/row', query_to_xml(CASE WHEN to_regclass('supabase_migrations.schema_migrations') IS NULL
         THEN 'SELECT NULL::text AS version WHERE false'
         ELSE 'SELECT version::text AS version FROM supabase_migrations.schema_migrations' END, false, false, ''))) AS r
), result AS (
  SELECT rf.position::int AS position, rf.migration, rf.path,
         coalesce(p.objects_expected, 0) AS objects_expected, coalesce(p.present, 0) AS present,
         coalesce(p.absent, 0) AS absent, coalesce(p.unknown_bodies, 0) AS unknown_bodies,
         CASE WHEN coalesce(p.objects_expected, 0) = 0 THEN 'UNKNOWN - introduces nothing observable'
              WHEN p.absent = 0 AND p.unknown_bodies = 0 THEN 'CONFIRMED APPLIED'
              WHEN p.present = 0 AND p.unknown_bodies = 0 THEN 'CONFIRMED NOT APPLIED'
              WHEN p.absent = 0 THEN 'APPLIED, BODIES DIFFER'
              ELSE 'PARTIALLY APPLIED' END AS evidence_status,
         (SELECT string_agg(j.release, ', ' ORDER BY j.release) FROM journal j
           WHERE position(split_part(rf.path, '/', 3) IN coalesce(j.manifest, '')) > 0
              OR position(rf.migration IN coalesce(j.manifest, '')) > 0) AS journal_releases,
         EXISTS (SELECT FROM cli WHERE cli.version = split_part(rf.migration, '_', 1)) AS cli_registered,
         (SELECT count(*) FROM cli) > 0 AS cli_history_exists,
         rf.prod_path_note
  FROM repo_files rf LEFT JOIN per_migration p ON p.migration = rf.migration
)
SELECT position, migration, evidence_status, objects_expected, present, absent, unknown_bodies,
       journal_releases, cli_registered,
       CASE WHEN (cli_registered OR journal_releases IS NOT NULL) AND evidence_status = 'CONFIRMED NOT APPLIED'
              THEN 'HISTORY MISMATCH - recorded, but its objects are absent'
            WHEN cli_history_exists AND NOT cli_registered AND evidence_status IN ('CONFIRMED APPLIED', 'APPLIED, BODIES DIFFER')
              AND migration NOT LIKE 'storage/%'
              THEN 'HISTORY MISMATCH - present in the schema, not registered in the CLI history'
            ELSE 'consistent' END AS history_check,
       CASE WHEN prod_path_note IS NOT NULL THEN 'PROD: do not run - ' || prod_path_note
            WHEN migration = 'storage/tasks-private-policies' AND evidence_status = 'PARTIALLY APPLIED'
              THEN 'Existing policies: upgrade tasks_file_select with supabase/storage/tasks-private-policies-202611140001.sql (after 202611140001)'
            WHEN evidence_status IN ('CONFIRMED NOT APPLIED', 'PARTIALLY APPLIED') THEN 'Candidate: review dependencies, then apply ' || path
            WHEN evidence_status = 'APPLIED, BODIES DIFFER' THEN 'Review the differing bodies in prod_gap_analysis.sql'
            WHEN evidence_status LIKE 'UNKNOWN%' THEN 'Check by hand (no observable objects)'
            ELSE 'none' END AS recommendation,
       path
FROM result ORDER BY position;
